from pathlib import Path
from html import escape
import json,re,shutil
R=Path(__file__).resolve().parent;site=R/'docs';site.mkdir(exist_ok=True);(site/'.nojekyll').write_text('')
catalog=json.loads((R/'catalog.json').read_text());cards=[]
for item in catalog:
 id=item['id'];version=item['version'];assert re.fullmatch('[a-z0-9-]+',id)
 theme=R/'themes'/id;assert theme.exists();shutil.copytree(theme/'preview',site/id,dirs_exist_ok=True)
 for p in (site/id).glob('*.png'):p.unlink()
 (site/'assets').mkdir(exist_ok=True)
 shutil.copy2(theme/'wordpress'/id/'screenshot.png',site/item['cover'])
 release=f'https://github.com/gonkfun/themes/releases/download/{id}-v{version}/'
 downloads=''.join(f'<a href="{release}{id}-{platform.lower()}-{version}.zip">{escape(platform)} ZIP ↓</a>' for platform in item['platforms'])
 cards.append(f'''<article class="card"><a class="cover" href="{id}/" aria-label="Preview {escape(item['name'])}"><img src="{escape(item['cover'])}" width="1200" height="900" alt="{escape(item['name'])} theme homepage"/></a><div class="card-body"><div class="eyebrow">THEME {len(cards)+1:02d} / {escape(item['category'])}</div><h2>{escape(item['name'])}</h2><p>{escape(item['description'])}</p><div class="tags">{''.join('<span>'+escape(p)+'</span>' for p in item['platforms'])}</div><div class="actions"><a class="primary" href="{id}/">Live preview ↗</a>{downloads}</div><a class="source" href="https://github.com/gonkfun/themes/tree/main/themes/{id}">Source &amp; installation guides ↗</a></div></article>''')
css='''*{box-sizing:border-box}body{margin:0;background:#101216;color:#f2f4f8;font:16px/1.7 system-ui,-apple-system,sans-serif}a{color:inherit;text-underline-offset:5px}a:focus-visible{outline:3px solid #8fbaff;outline-offset:5px}.wrap{max-width:1180px;width:calc(100% - 48px);margin:auto}header{border-bottom:1px solid #39414f}header .wrap{display:flex;justify-content:space-between;align-items:center;min-height:90px;gap:24px}header a{text-decoration:none;min-height:44px;display:inline-flex;align-items:center}.brand{font-size:23px;font-weight:700;letter-spacing:-.8px}.brand span{color:#8fbaff}nav{display:flex;gap:25px;font-size:14px}.hero{padding:80px 0 55px;max-width:850px}.eyebrow{font:11px/1.5 ui-monospace,monospace;letter-spacing:1.5px;color:#aab3c2;text-transform:uppercase}h1{font-size:clamp(42px,6vw,76px);font-weight:600;line-height:1.08;letter-spacing:-3px;margin:20px 0 26px}h1 span{color:#8fbaff}.hero p{font-size:18px;color:#aab3c2;max-width:620px}.grid{display:grid;grid-template-columns:minmax(0,1fr);gap:32px}.card{border:1px solid #39414f;background:#191c22;border-radius:18px;overflow:hidden;display:grid;grid-template-columns:1.1fr 1fr;min-width:0}.cover{display:block;background:#222731;overflow:hidden}.cover img{display:block;width:100%;height:100%;object-fit:cover;object-position:top}.card-body{padding:34px}h2{font-size:35px;font-weight:600;letter-spacing:-1px;margin:14px 0 10px}.card p{font-size:15px;color:#aab3c2}.tags{display:flex;flex-wrap:wrap;gap:10px;margin:22px 0}.tags span{padding:6px 12px;border:1px solid #39414f;border-radius:999px;font-size:12px}.actions{display:flex;gap:10px;flex-wrap:wrap}.actions a{min-height:44px;display:inline-flex;align-items:center;padding:10px 16px;text-decoration:none;font-size:13px;border:1px solid #46546b;border-radius:999px}.actions .primary{background:#8fbaff;color:#101b30;border-color:#8fbaff;font-weight:650}.source{display:inline-flex;align-items:center;min-height:44px;font-size:13px;margin-top:16px;color:#bfd4f9}.note{padding:26px 0;color:#aab3c2;font-size:14px;max-width:900px}footer{border-top:1px solid #39414f;margin-top:50px;padding:28px 0 40px;font-size:13px;color:#aab3c2}footer .wrap{display:flex;justify-content:space-between;gap:25px;flex-wrap:wrap}footer a{color:#8fbaff}.skip{position:absolute;top:-100px;left:20px}.skip:focus{top:15px;background:#8fbaff;color:#101216;padding:12px;z-index:5}@media(max-width:750px){.wrap{width:calc(100% - 32px)}header .wrap{min-height:80px}.brand{font-size:20px}nav{gap:16px;font-size:12px}.hero{padding:46px 0 32px}h1{letter-spacing:-1.8px}.card{grid-template-columns:1fr}.cover{aspect-ratio:16/10}.card-body{padding:25px}.hero p{font-size:16px}}'''
(site/'index.html').write_text('''<!doctype html><html lang="en"><head><meta charset="utf-8"/><meta name="viewport" content="width=device-width,initial-scale=1"/><title>Gonk Themes — Free themes for crypto communities</title><meta name="description" content="Original free Blogger and WordPress themes for crypto communities. Browse live previews, download installable themes and explore the open source."/><link rel="canonical" href="https://gonkfun.github.io/"/><link rel="icon" type="image/svg+xml" href="assets/favicon.svg"/><style>'''+css+'''</style></head><body><a class="skip" href="#themes">Skip to themes</a><header><div class="wrap"><a class="brand" href="./">gonk<span> / themes</span></a><nav aria-label="Main"><a href="https://github.com/gonkfun/themes">GitHub ↗</a><a href="https://gonk.fun/">gonk.fun ↗</a></nav></div></header><main class="wrap"><section class="hero"><div class="eyebrow">Original design. Open source.</div><h1>A home for your<br/><span>corner of crypto.</span></h1><p>Free themes for the people writing, building and bringing communities together. Start with one you like. Make it your own.</p></section><section class="grid" id="themes" aria-label="Available themes">'''+''.join(cards)+'''</section><p class="note">Each card lists its available downloads. Blogger ZIPs include XML, WordPress ZIPs install as themes, and React ZIPs include the starter source. Previews use fictional sample content. WordPress needs hosting that supports custom themes; GitHub Pages hosts the static previews.</p></main><footer><div class="wrap"><span>GPL-2.0-or-later · Free to use and modify.</span><span>Powered by <a href="https://gonk.fun/" rel="nofollow">gonk.fun</a></span></div></footer></body></html>''')
print(f'Built gallery and {len(catalog)} static theme preview.')
